const Settings = ({
	profilePicExists,
	nameInitials,
	profilePic,
	firstName,
	lastName,
	businessName,
	closeSettingsTooltip,
}) => {
	const { pathname } = useLocation();

	const navigate = useNavigate();

	const [info, setInfo] = useState({
		workspaceModalOpen: false,
	});

	const {
		profileInfo: { tenantUserAccessControls },
	} = useContext(Context);

	const fullName = `${firstName ?? ''} ${lastName ?? ''}`;
	const isAdmin = tenantUserAccessControls?.role === 'admin';

	return (
		<div className={s.settingsContainer}>
			<header className={s.userInfo}>
				{profilePicExists ? (
					<img className={s.profileImg} src={profilePic} alt="profile" />
				) : (
					<p className={s.nameInitials}>{nameInitials}</p>
				)}
				<div className={s.userInfoDetails}>
					<p className={s.nameAndRole}>
						<span className={s.fullName}>{fullName}</span>{' '}
						<span className={s.role}>{isAdmin ? '(Admin)' : '(Member)'}</span>
					</p>
					<p className={s.businessName}>{businessName}</p>
				</div>
				<Tooltip
					open={info.switchWorkspaceTooltipOpen}
					title={
						<div className={s.switchWorkspaceTooltip}>
							<span>Switch Workspace</span>
						</div>
					}
					placement="bottom"
					arrow={false}
					color="transparent"
				>
					<button
						className={s.switchWorkspaceButton}
						onClick={(e) => {
							e.stopPropagation();
							setInfo((prev) => ({
								...prev,
								workspaceModalOpen: true,
							}));
							closeSettingsTooltip();
						}}
					>
						<svg
							xmlns="http://www.w3.org/2000/svg"
							width="20"
							height="20"
							viewBox="0 0 20 20"
							fill="none"
						>
							<g clip-path="url(#clip0_155_2914)">
								<path
									d="M13.75 11.25L16.25 13.75L13.75 16.25"
									stroke="var(--primary-font)"
									stroke-width="1.25"
									stroke-linecap="round"
									stroke-linejoin="round"
								/>
								<path
									d="M3.75 13.75H16.25"
									stroke="var(--primary-font)"
									stroke-width="1.25"
									stroke-linecap="round"
									stroke-linejoin="round"
								/>
								<path
									d="M6.25 8.75L3.75 6.25L6.25 3.75"
									stroke="var(--primary-font)"
									stroke-width="1.25"
									stroke-linecap="round"
									stroke-linejoin="round"
								/>
								<path
									d="M16.25 6.25H3.75"
									stroke="var(--primary-font)"
									stroke-width="1.25"
									stroke-linecap="round"
									stroke-linejoin="round"
								/>
							</g>
							<defs>
								<clipPath id="clip0_155_2914">
									<rect width="20" height="20" fill="white" />
								</clipPath>
							</defs>
						</svg>
					</button>
				</Tooltip>
			</header>
			<div className={s.settingsItems}>
				{settingsItems.map((settingItem) => (
					<div
						onClick={() => {
							if (settingItem.route) {
								navigate(settingItem.route);
							} else {
								settingItem.handleClick();
							}
						}}
						key={settingItem.id}
						className={`${s.settingItem} ${
							settingItem.route && settingItem.route.includes(pathname)
								? s.active
								: ''
						}`}
					>
						{settingItem.icon}
						<span className={s.settingItemLabel}>{settingItem.label}</span>
					</div>
				))}
			</div>
			<button className={s.logoutButton} onClick={() => logout()}>
				<svg
					xmlns="http://www.w3.org/2000/svg"
					width="18"
					height="19"
					viewBox="0 0 18 19"
					fill="none"
				>
					<g clip-path="url(#clip0_155_2902)">
						<path
							d="M7.875 3.3125H3.375V15.6875H7.875"
							stroke="#E03F4F"
							stroke-width="1.125"
							stroke-linecap="round"
							stroke-linejoin="round"
						/>
						<path
							d="M7.875 9.5H15.75"
							stroke="#E03F4F"
							stroke-width="1.125"
							stroke-linecap="round"
							stroke-linejoin="round"
						/>
						<path
							d="M12.9375 6.6875L15.75 9.5L12.9375 12.3125"
							stroke="#E03F4F"
							stroke-width="1.125"
							stroke-linecap="round"
							stroke-linejoin="round"
						/>
					</g>
					<defs>
						<clipPath id="clip0_155_2902">
							<rect
								width="18"
								height="18"
								fill="white"
								transform="translate(0 0.5)"
							/>
						</clipPath>
					</defs>
				</svg>
				<span>Logout</span>
			</button>
			<SwitchWorkspaceModal
				isOpen={info.workspaceModalOpen}
				closeWorkspaceModal={() => {
					setInfo((prev) => ({ ...prev, workspaceModalOpen: false }));
				}}
			/>
		</div>
	);
};

export default Settings;
